def is_valid_pillar_placement(centers, N):
    """Checks if a set of pillar centers is valid for an NxN grid (N=18 or N=6 for testing)."""
    if len(centers) < 2:
        return True

    centers_list = list(centers)

    for i in range(len(centers_list)):
        for j in range(i + 1, len(centers_list)):
            c1 = centers_list[i]
            c2 = centers_list[j]

            # Distance check: must be at least 2 in L_infinity norm
            dist_i = abs(c1[0] - c2[0])
            dist_j = abs(c1[1] - c2[1])

            if max(dist_i, dist_j) < 2:
                return False
    return True

# Test case for N=6
N_test = 6
# Valid placement: (1,1), (1,3), (3,1), (3,3)
P_valid = {(1, 1), (1, 3), (3, 1), (3, 3)}
print(f"Test 1 (Valid): {is_valid_pillar_placement(P_valid, N_test)}")

# Invalid placement: (1,1) and (2,1) -> max(1, 0) = 1
P_invalid_side = {(1, 1), (2, 1)}
print(f"Test 2 (Invalid Side): {is_valid_pillar_placement(P_invalid_side, N_test)}")

# Invalid placement: (1,1) and (2,2) -> max(1, 1) = 1
P_invalid_vertex = {(1, 1), (2, 2)}
print(f"Test 3 (Invalid Vertex): {is_valid_pillar_placement(P_invalid_vertex, N_test)}")

# Valid placement separated by 2: (1,1) and (3,3) -> max(2, 2) = 2
P_valid_separated = {(1, 1), (3, 3)}
print(f"Test 4 (Valid Separated): {is_valid_pillar_placement(P_valid_separated, N_test)}")

